        def p_division_of_units(p):
            """
            division_of_units : DIVISION unit_expression
                              | unit_expression DIVISION combined_units
            """
            if len(p) == 3:
                p[0] = p[2] ** -1
            else:
                # Ensure chained divisions are treated as left-associative by
                # placing all units to the right of '/' in the denominator.
                u = p[3]
                if isinstance(u, core.CompositeUnit):
                    denom = core.dimensionless_unscaled
                    for base, power in zip(u.bases, u.powers):
                        if power:
                            denom = denom * (base ** (-abs(int(power))))
                    p[0] = p[1] * denom
                else:
                    p[0] = p[1] / u

